var points = JSON.parse(metadata.chainages);

return {msg: {
    chainages: points
}, metadata: {}, msgType: 'POST_ATTRIBUTES_REQUEST'};


// Precompute splines from reference points
function buildSplines(points) {
    var n = points.size();
    chainagePoints = points;
    minChainage = points[0][0];
    maxChainage = points[n-1][0];

    if (n <= 1) return;

    // Extract chainages and coordinates
    var s = [];
    var x = [];
    var y = [];
    foreach (point : points) {
        s.push(point[0]);
        x.push(point[1]);
        y.push(point[2]);
    }

    splineX = calculateCubicSpline(s, x);
    splineY = calculateCubicSpline(s, y);
}

// Calculate cubic spline coefficients for one dimension
function calculateCubicSpline(s, vals) {
    var n = s.size();
    if (n <= 1) return [];

    // Initialize arrays
    var a = [];
    var b = [];
    var c = [];
    var d = [];
    var h = [];
    var alpha = [];

    // Calculate differences
    for (var i = 0; i < n-1; i++) {
        h.push(s[i+1] - s[i]);
    }

    // Natural spline conditions (second derivatives = 0 at ends)
    c[0] = c[n-1] = 0.0;

    // Calculate alpha
    for (var i = 1; i < n-1; i++) {
        alpha[i] = 3/h[i]*(vals[i+1]-vals[i]) - 3/h[i-1]*(vals[i]-vals[i-1]);
    }

    // Solve tridiagonal system: Thomas algorithm
    var l = [];
    var mu = [];
    var z = [];
    l[0] = 1; mu[0] = z[0] = 0;

    for (var i = 1; i < n-1; i++) {
        l[i] = 2*(s[i+1]-s[i-1]) - h[i-1]*mu[i-1];
        mu[i] = h[i]/l[i];
        z[i] = (alpha[i]-h[i-1]*z[i-1])/l[i];
    }

    l[n-1] = 1;
    z[n-1] = 0;
    c = []; // Clear then recalc
    c[n-1] = 0;

    // Back substitution
    for (var j = n-2; j >= 0; j--) {
        c[j] = z[j] - mu[j]*c[j+1];
        b[j] = (vals[j+1]-vals[j])/h[j] - h[j]*(c[j+1]+2*c[j])/3;
        d[j] = (c[j+1]-c[j])/(3*h[j]);
        a[j] = vals[j];
    }

    // Return coefficients [a, b, c, d] for each segment
    var coeffs = [];
    for (var i = 0; i < n-1; i++) {
        coeffs.push([a[i], b[i], c[i], d[i]]);
    }
    return coeffs;
}

// Evaluate polynomial
function evaluatePolynomial(s, s0, coeffs) {
    var ds = s - s0;
    return coeffs[0] + 
           coeffs[1]*ds + 
           coeffs[2]*(ds*ds) + 
           coeffs[3]*(ds*ds*ds);
}

// Find spline segment index for given chainage
function findSegmentIndex(s) {
    // Binary search for efficient segment lookup
    var low = 0;
    var high = chainagePoints.size() - 1;

    while (low <= high) {
        if (s < minChainage) return 0;
        if (s > maxChainage) return chainagePoints.size()-2;

        var mid = Math.floor((low + high) / 2);
        if (s >= chainagePoints[mid][0] && 
            (mid == chainagePoints.size()-1 || 
             s < chainagePoints[mid+1][0])) {
            return Math.max(0, Math.min(mid, chainagePoints.size()-2));
        }
        else if (s < chainagePoints[mid][0]) {
            high = mid - 1;
        }
        else {
            low = mid + 1;
        }
    }
    return 0;
}

// Find chainage for new (lon, lat)
function findChainageSpline(lon, lat) {
    if (splineX.size() == 0 || splineY.size() == 0) {
        // Splines not initialized
        return null;
    }

    // Step 1: Find closest reference point (chainage anchor)
    var bestIndex = 0;
    var bestDist = Double.MAX_VALUE;

    for (var i = 0; i < chainagePoints.size(); i++) {
        var refLon = chainagePoints[i][1];
        var refLat = chainagePoints[i][2];
        var dist = Math.sqrt(
            Math.pow(lon - refLon, 2) + 
            Math.pow(lat - refLat, 2)
        );

        if (dist < bestDist) {
            bestDist = dist;
            bestIndex = i;
        }
    }

    // Step 2: Search neighboring segments (3 segments total)
    var candidateSegments = [
        Math.max(0, bestIndex - 1),
        bestIndex,
        Math.min(splineX.size()-1, bestIndex + 1)
    ];

    // Step 3: Fine search in candidate segments
    var overallBestS = minChainage;
    var overallBestDist = Double.MAX_VALUE;

    foreach (segIdx : candidateSegments) {
        var sSegStart = chainagePoints[segIdx][0];
        var sSegEnd = chainagePoints[segIdx+1][0];
        var steps = 10; // Samples per segment

        for (var i = 0; i <= steps; i++) {
            var s = sSegStart + (sSegEnd - sSegStart) * i/steps;
            var interpLon = getSplineLon(s);
            var interpLat = getSplineLat(s);

            var dist = Math.sqrt(
                Math.pow(lon - interpLon, 2) + 
                Math.pow(lat - interpLat, 2)
            );

            if (dist < overallBestDist) {
                overallBestDist = dist;
                overallBestS = s;
            }
        }
    }

    return overallBestS;
}

// Get interpolated longitude
function getSplineLon(s) {
    var segIdx = findSegmentIndex(s);
    var s0 = chainagePoints[segIdx][0];
    return evaluatePolynomial(s, s0, splineX[segIdx]);
}

// Get interpolated latitude
function getSplineLat(s) {
    var segIdx = findSegmentIndex(s);
    var s0 = chainagePoints[segIdx][0];
    return evaluatePolynomial(s, s0, splineY[segIdx]);
}

var statusMsg = {};

if (null != msg.?longitude84 && null != msg.?latitude84 && 0.0 != msg.?longitude84 && 0.0 != msg.?latitude84) {
    statusMsg.put("geoStatus", 'connected and normal');
}
else if (null != msg.?longitude84 && null != msg.?latitude84 && 0.0 == msg.?longitude84 && 0.0 == msg.?latitude84) {
    statusMsg.put("geoStatus", 'connected but abnormal');
}
else {
    statusMsg.put("geoStatus", 'disconnected');
}

return {msg: statusMsg, metadata: metadata, msgType: 'POST_ATTRIBUTES_REQUEST'};

// Main Script Body
if (null != msg.?longitude84 && null != msg.?latitude84 && 0.0 != msg.?longitude84 && 0.0 != msg.?latitude84 && null != metadata.?ss_chainages) {
    var chainages = decodeToJson(metadata.ss_chainages);
    var currentPoint = [msg.longitude84, msg.latitude84];
    var chainage = linearReference(currentPoint, chainages);
    msg.put("chainage", chainage);

} else {
    // do nothing if inputs are invalid
}

return {
    msg: msg,
    metadata: {
        deviceType: metadata.deviceType,
        deviceName: metadata.deviceName,
        ts: metadata.ts
    },
    msgType: msgType
};

// --- Helper Functions ---

function linearReference(currentPoint, chainages) {
    if (chainages == null || chainages.size() < 2) {
        // Not enough points to form a line
        return -1.0;
    }

    var minPerpDist = -1.0;
    var finalProjectedMilestone = -1.0;

    // Iterate through each line segment of the chainage path
    for (var i = 0; i < chainages.size() - 1; i++) {
        var segmentStart = chainages[i];       // e.g., [0, [112.8, 28.2]]
        var segmentEnd = chainages[i+1];       // e.g., [10, [112.9, 28.3]]

        var startMilestone = segmentStart[0];
        var startPoint = segmentStart[1];
        var endMilestone = segmentEnd[0];
        var endPoint = segmentEnd[1];

        // Calculate the three sides of the triangle formed by the currentPoint and the segment endpoints
        var distToStart = haversineDistance(currentPoint, startPoint);
        var distToEnd = haversineDistance(currentPoint, endPoint);
        var segmentLength = haversineDistance(startPoint, endPoint);

        var perpDist;
        var projectedMilestone;

        // Process only if the segment has a valid length
        if (segmentLength > 0) {
            // Case 1: The closest point on the line is the segment's start point
            if (distToEnd * distToEnd >= distToStart * distToStart + segmentLength * segmentLength) {
                perpDist = distToStart;
                projectedMilestone = startMilestone;
            } 
            // Case 2: The closest point on the line is the segment's end point
            else if (distToStart * distToStart >= distToEnd * distToEnd + segmentLength * segmentLength) {
                perpDist = distToEnd;
                projectedMilestone = endMilestone;
            } 
            // Case 3: The closest point (projection) lies on the segment itself
            else {
                // Calculate the perpendicular distance from the point to the segment using Heron's formula for area
                var s = (distToStart + distToEnd + segmentLength) / 2.0;
                var area = Math.sqrt(s * (s - distToStart) * (s - distToEnd) * (s - segmentLength));
                perpDist = 2.0 * area / segmentLength;

                // Calculate the distance from the start of the segment to the projected point
                // Using the Law of Cosines: projectedDist = (a^2 + c^2 - b^2) / 2c
                var distAlongSegment = (distToStart * distToStart + segmentLength * segmentLength - distToEnd * distToEnd) / (2.0 * segmentLength);
                projectedMilestone = startMilestone + distAlongSegment;
            }

            // If this segment is the closest one we've found so far, store its result
            if (minPerpDist < 0 || perpDist < minPerpDist) {
                minPerpDist = perpDist;
                finalProjectedMilestone = projectedMilestone;
            }
        }
    }
    return finalProjectedMilestone;
}


// Calculates the Haversine distance between two points in meters.
function haversineDistance(pointA, pointB) {
    var lon1 = pointA[0];
    var lat1 = pointA[1];
    var lon2 = pointB[0];
    var lat2 = pointB[1];

    var degToRad = Math.PI / 180.0;
    var latRad1 = lat1 * degToRad;
    var lonRad1 = lon1 * degToRad;
    var latRad2 = lat2 * degToRad;
    var lonRad2 = lon2 * degToRad;

    var dLat = latRad2 - latRad1;
    var dLon = lonRad2 - lonRad1;

    var a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(latRad1) * Math.cos(latRad2) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
    var c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    // Earth's radius in meters
    var R = 6371000; 

    return R * c;
}

function map(list, f) {
    var newList = [];
    foreach (element : list) {
        newList.push(f(element));
    }
    return newList;
}

function transpose(matrix) {
    if (matrix.size() == 0) {
        return [];
    }
    var transposed = [];
    var colCount = matrix[0].size();
    for (var colIndex = 0; colIndex < colCount; colIndex++) {
        var newRow = [];
        foreach (row : matrix) {
            newRow.push(row[colIndex]);
        }
        transposed.push(newRow);
    }
    return transposed;
}

function diff(list, f) {
    if (list.size == 0 || list.size == 1) {
        return [];
    } else {
        var output = [];
        for (var i = 0; i < list.size() - 1; i++) {
            output.push(f(list[i + 1], list[i]));
        }
        return output;
    }
}
